import React, { useEffect, useRef, useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome'
import { faAt } from '@fortawesome/free-solid-svg-icons'
import './Contact.css';


export default function Contact() {
  const ref = useRef(null);
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      entries => entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); }),
      { threshold: 0.1 }
    );
    ref.current?.querySelectorAll('.reveal').forEach(el => obs.observe(el));
    return () => obs.disconnect();
  }, []);

  const copy = () => {
    navigator.clipboard.writeText('nattinan.ms@hotmail.com').catch(() => {});
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <section className="contact section" id="contact" ref={ref}>
      <div className="section-header reveal">
        <span className="section-tag">Contact</span>
        <h2 className="section-title">Let's Work <span>Together</span></h2>
        <p className="section-sub">Open for new opportunities — feel free to reach out!</p>
      </div>

      <div className="contact__grid reveal">
        <div className="contact__card" onClick={copy}>
          <FontAwesomeIcon icon={faAt} />
          <div>
            <div className="cc-label">Email</div>
            <div className="cc-val">nattinan.ms@hotmail.com</div>
          </div>
          <span className="cc-copy">{copied ? '✓' : 'Copy'}</span>
        </div>
        <div className="contact__card">
          <span className="cc-icon">📞</span>
          <div>
            <div className="cc-label">Phone</div>
            <div className="cc-val">061-616-9669</div>
          </div>
        </div>
        <div className="contact__card">
          <span className="cc-icon">📍</span>
          <div>
            <div className="cc-label">Location</div>
            <div className="cc-val">Bang Kho Laem, Bangkok 10120</div>
          </div>
        </div>
        <a className="contact__card contact__card--link" href="https://nattinan.port.com" target="_blank" rel="noopener noreferrer">
          <span className="cc-icon">🌐</span>
          <div>
            <div className="cc-label">Portfolio</div>
            <div className="cc-val">nattinan.port.com</div>
          </div>
          <span className="cc-arrow">→</span>
        </a>
        <a className="contact__card contact__card--link" href="https://linkedin.com/in/your-profile" target="_blank" rel="noopener noreferrer">
          <span className="cc-icon">💼</span>
          <div>
            <div className="cc-label">LinkedIn</div>
            <div className="cc-val">linkedin.com/in/your-profile</div>
          </div>
          <span className="cc-arrow">→</span>
        </a>
      </div>
    </section>
  );
}
